$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'ESLangGraphAdapter.psm1') -Force
$cases=[Collections.Generic.List[object]]::new();function C($n,$b){[void]$cases.Add([pscustomobject]@{case=$n;status=$(if($b){'passed'}else{'failed'})})}
$s=New-ESLangGraphState -GraphId 'focus-graph' -TaskId 'task-1';$s=Invoke-ESLangGraphNode -State $s -NodeId 'propose' -Update @{focus='x'} -Interrupt;C 'interrupt' ($s.status -eq 'interrupted');$cp=New-ESLangGraphCheckpoint -State $s;$r=Resume-ESLangGraphCheckpoint -Checkpoint $cp -TaskId 'task-1';C 'resume' ($r.status -eq 'running');$r=Invoke-ESLangGraphNode -State $r -NodeId 'confirm' -Update @{confirmed=$true};C 'state-update' ($r.values.confirmed -eq $true);C 'event-replay' ((Test-ESLangGraphEventChain -State $r).status -eq 'passed');$bad=$cp|ConvertTo-Json -Depth 20|ConvertFrom-Json;$bad.values.focus='tampered';try{Resume-ESLangGraphCheckpoint -Checkpoint $bad -TaskId 'task-1';C 'tamper-rejected' $false}catch{C 'tamper-rejected' $true};$failed=@($cases|? status -eq 'failed');[pscustomobject]@{schemaVersion=1;validator='Test-ESLangGraphAdapter';status=$(if($failed.Count){'failed'}else{'passed'});caseCount=$cases.Count;passedCount=@($cases|? status -eq 'passed').Count;failedCount=$failed.Count;cases=@($cases);runtimeStatus='runtime-not-run';claimsNotProven=@('External LangGraph runtime equivalence','Unity/host runtime')}|ConvertTo-Json -Depth 10;if($failed.Count){exit 1}
